//==============================================================================
// COLOR PALETTES AND CONTROLS
//==============================================================================
#define BASE_COLOR vec3(0.2, 0.4, 0.6)
#define HIGHLIGHT_COLOR vec3(0.8, 0.9, 1.0)
#define GLOW_COLOR vec3(1.0, 0.7, 0.5)

vec3 palette(float t) {
    float mixFactor = sin(t * 2.0) * 0.5 + 0.5; // Faster oscillation
    return mix(BASE_COLOR, HIGHLIGHT_COLOR, mixFactor);
}

//==============================================================================
// SDF (SIGNED DISTANCE FIELD) FUNCTIONS
//==============================================================================
// Circular SDF
float sdCircle(vec2 p, float radius) {
    return length(p) - radius;
}

// Box SDF with adjustable roundness
float sdRoundedBox(vec2 p, vec2 size, float roundness) {
    vec2 d = abs(p) - size;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - roundness;
}

// Wave Pattern for a soft, dynamic fill
float wavePattern(vec2 p, float frequency, float amplitude, float speed) {
    return sin(p.x * frequency + iTime * speed) * amplitude;
}

//==============================================================================
// ROTATION MATRIX
//==============================================================================
mat2 rotationMatrix(float angle) {
    return mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
}

//==============================================================================
// MAIN FUNCTION
//==============================================================================
void mainImage(out vec4 fragColor, vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float time = iTime * 0.5;

    // Rotate UV space dynamically
    uv *= rotationMatrix(time);

    // Initialize color
    vec3 color = vec3(0.0);

    // Layered shapes with waves and glow
    for (float i = 0.5; i > 0.1; i -= 0.129) {
        // Layer-specific rotation and scaling
        vec2 p = uv * (1.0 + i * 0.5);
        p *= rotationMatrix(i * 3.14);

        // Shape and wave interaction
        float sdf = sdRoundedBox(p, vec2(i * 0.5, i * 0.25), 0.1);
        float wave = wavePattern(p, 15.0, 0.05, 2.0);

        // Combine effects
        float glow = exp(-abs(sdf + wave) * 20.0) * 0.7;
        color += palette(i + time) * glow;
    }

    // Background with subtle gradient
    vec3 background = mix(vec3(0.05, 0.05, 0.1), GLOW_COLOR, 0.2);
    fragColor = vec4(mix(background, color, length(color)), 1.0);
}
